#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int longestBalancedSubstring(std::string s) {
        int totalZeros = 0, totalOnes = 0;
        for (char c : s) {
            if (c == '0') totalZeros++;
            else totalOnes++;
        }
        int n = s.length();
        std::vector<int> prefZeros(n + 1, 0), prefOnes(n + 1, 0);
        std::unordered_map<int, std::vector<int>> firstOcc;
        firstOcc[0].push_back(0);
        int pref = 0;
        for (int i = 0; i < n; ++i) {
            prefZeros[i + 1] = prefZeros[i] + (s[i] == '0' ? 1 : 0);
            prefOnes[i + 1] = prefOnes[i] + (s[i] == '1' ? 1 : 0);
            pref += (s[i] == '1' ? 1 : -1);
            if (firstOcc[pref].size() < 5) {
                firstOcc[pref].push_back(i + 1);
            }
        }
        int maxLen = 0, curPref = 0;
        for (int i = 1; i <= n; ++i) {
            curPref += (s[i - 1] == '1' ? 1 : -1);
            if (firstOcc.count(curPref)) {
                int j = firstOcc[curPref][0];
                if (j < i) maxLen = std::max(maxLen, i - j);
            }
            int target = curPref - 2;
            if (firstOcc.count(target)) {
                for (int j : firstOcc[target]) {
                    if (j < i && totalZeros - (prefZeros[i] - prefZeros[j]) > 0) {
                        maxLen = std::max(maxLen, i - j);
                        break;
                    }
                }
            }
            target = curPref + 2;
            if (firstOcc.count(target)) {
                for (int j : firstOcc[target]) {
                    if (j < i && totalOnes - (prefOnes[i] - prefOnes[j]) > 0) {
                        maxLen = std::max(maxLen, i - j);
                        break;
                    }
                }
            }
        }
        return maxLen;
    }
};

import java.util.*;

class Solution {
    public int longestBalancedSubstring(String s) {
        int totalZeros = 0, totalOnes = 0;
        for (char c : s.toCharArray()) {
            if (c == '0') totalZeros++;
            else totalOnes++;
        }
        int n = s.length();
        int[] prefZeros = new int[n + 1];
        int[] prefOnes = new int[n + 1];
        Map<Integer, List<Integer>> firstOcc = new HashMap<>();
        firstOcc.put(0, new ArrayList<>(List.of(0)));
        int pref = 0;
        for (int i = 0; i < n; i++) {
            prefZeros[i + 1] = prefZeros[i] + (s.charAt(i) == '0' ? 1 : 0);
            prefOnes[i + 1] = prefOnes[i] + (s.charAt(i) == '1' ? 1 : 0);
            pref += (s.charAt(i) == '1' ? 1 : -1);
            firstOcc.putIfAbsent(pref, new ArrayList<>());
            if (firstOcc.get(pref).size() < 5) {
                firstOcc.get(pref).add(i + 1);
            }
        }
        int maxLen = 0;
        int curPref = 0;
        for (int i = 1; i <= n; i++) {
            curPref += (s.charAt(i - 1) == '1' ? 1 : -1);
            if (firstOcc.containsKey(curPref)) {
                int j = firstOcc.get(curPref).get(0);
                if (j < i) maxLen = Math.max(maxLen, i - j);
            }
            int target = curPref - 2;
            if (firstOcc.containsKey(target)) {
                for (int j : firstOcc.get(target)) {
                    if (j < i && totalZeros - (prefZeros[i] - prefZeros[j]) > 0) {
                        maxLen = Math.max(maxLen, i - j);
                        break;
                    }
                }
            }
            target = curPref + 2;
            if (firstOcc.containsKey(target)) {
                for (int j : firstOcc.get(target)) {
                    if (j < i && totalOnes - (prefOnes[i] - prefOnes[j]) > 0) {
                        maxLen = Math.max(maxLen, i - j);
                        break;
                    }
                }
            }
        }
        return maxLen;
    }
}

